#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;
vector<long long> fact, invfact;

long long pow_mod(long long x, long long y, long long p) {
    long long res = 1LL;
    while (y > 0) {
        if (y & 1) {
            res = (res * x) % p;
        }
        x = (x * x) % p;
        y >>= 1;
    }
    return res % p;
}

long long ncr(int n, int r) {
    return (((fact[n] * invfact[r]) % MOD) * invfact[n - r]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    fact.resize(200001);
    invfact.resize(200001);
    fact[0] = 1LL;
    invfact[0] = 1LL;
    for (int i = 1; i <= 200000; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
        invfact[i] = pow_mod(fact[i], MOD - 2, MOD);
    }
    long long n, k;
    cin >> n >> k;
    if (k > n) {
        cout << 0 << "\n";
        return 0;
    }
    k = n - k;
    long long ans = 0LL;
    for (int i = 0; i <= k; i++) {
        long long curr = (ncr(k, i) * pow_mod(k - i, n, MOD)) % MOD;
        if (i % 2 == 0)
            ans += curr;
        else
            ans -= curr;
        ans %= MOD;
    }
    ans = (ans * ncr(n, k)) % MOD;
    if (n - k == 0)
        cout << ans << "\n";
    else
        cout << (2 * ans) % MOD << "\n";
    return 0;
}

